'use client';

import { FormEvent, useEffect, useMemo, useRef, useState } from 'react';
import { BarChart3, BookOpen, Bone, Check, ChevronRight, CirclePlus, Database, Download, Dumbbell, History, Info, LayoutDashboard, LoaderCircle, LogOut, MoreHorizontal, Play, Plus, Save, Settings, Trash2, X } from 'lucide-react';
import { Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { hasSupabaseConfig, supabase } from '@/lib/supabase';

type WeightDirection = 'higher_is_better' | 'lower_is_better';
type MuscleGroup = { id: string; name: string; position: number };
type Muscle = { id: string; name: string; group_id: string; position: number; muscle_groups?: MuscleGroup | null };
type ExerciseTarget = { role: 'primary' | 'secondary'; muscles?: Muscle | null; muscle_groups?: MuscleGroup | null };
type Exercise = { id: string; name: string; primary_muscle: string | null; equipment: string | null; weight_direction: WeightDirection; created_by: string; exercise_muscles?: ExerciseTarget[] };
type Routine = { id: string; name: string; description: string | null; owner_id: string; copied_from_routine_id: string | null; archived_at: string | null; profiles?: { display_name: string | null } | null; routine_items?: RoutineItem[] };
type RoutineItem = { id: string; exercise_id: string; position: number; default_setup_label: string | null; exercises?: Exercise | null };
type Workout = { id: string; title: string | null; started_at: string; finished_at: string | null; notes: string | null; session_exercises?: SessionExercise[] };
type SessionExercise = { id: string; session_id: string; exercise_id: string; position: number; setup_label: string | null; notes: string | null; exercises?: Exercise | null; sets?: SetRow[] };
type SetRow = { id: string; session_exercise_id: string; set_number: number; set_type: string; reps: number; weight_kg: number; note: string | null };
type Profile = { id: string; display_name: string | null; role: 'member' | 'admin'; default_set_count: number };
type Suggestion = { id: string; suggestion: string; status: string; exercises?: { name: string } | null; profiles?: { display_name: string | null } | null };
type Screen = 'home' | 'workout' | 'routines' | 'history' | 'progress' | 'catalog' | 'muscles' | 'more' | 'profile';
type BeforeInstallPromptEvent = Event & { prompt: () => Promise<void>; userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }> };

const setTypes = ['standard', 'failure', 'drop_set', 'back_off', 'amrap'];
const nav = [
  ['home', LayoutDashboard, 'Home'], ['workout', Dumbbell, 'Workout'], ['progress', BarChart3, 'Progress'], ['history', History, 'History'], ['more', MoreHorizontal, 'More'],
] as const;

function errMessage(error: unknown) {
  if (error instanceof Error) return error.message;
  if (typeof error === 'object' && error && 'message' in error && typeof error.message === 'string') return error.message;
  if (typeof error === 'string') return error;
  return 'Something went wrong. Please try again.';
}
function dateLabel(value: string) { return new Intl.DateTimeFormat(undefined, { weekday: 'short', month: 'short', day: 'numeric' }).format(new Date(value)); }
function completedSets(sets: SetRow[] = []) { return sets.filter((set) => Number(set.reps) > 0); }
function bestWeight(sets: SetRow[] = [], direction: WeightDirection = 'higher_is_better') {
  const recorded = completedSets(sets).map((set) => Number(set.weight_kg));
  if (!recorded.length) return null;
  return direction === 'lower_is_better' ? Math.min(...recorded) : Math.max(...recorded);
}
function bestSetLabel(sets: SetRow[] = [], direction: WeightDirection = 'higher_is_better') {
  const value = bestWeight(sets, direction);
  if (value === null) return 'no completed sets';
  return direction === 'lower_is_better' ? `best ${value} kg assistance` : `best ${value} kg`;
}
function exerciseDetails(exercise: Exercise) {
  const directGroups = new Set((exercise.exercise_muscles ?? []).flatMap((target) => target.muscle_groups ? [target.muscle_groups.id] : []));
  const targets = (exercise.exercise_muscles ?? []).flatMap((target) => {
    const role = target.role === 'secondary' ? 'secondary' : 'primary';
    if (target.muscles) { const group = target.muscles.muscle_groups; return [`${target.muscles.name} (${role})`, ...(group && !directGroups.has(group.id) ? [`${group.name} (${role} via ${target.muscles.name})`] : [])]; }
    return target.muscle_groups ? [`${target.muscle_groups.name} (${role})`] : [];
  }).join(', ');
  return [...[targets || exercise.primary_muscle, exercise.equipment].filter(Boolean), exercise.weight_direction === 'lower_is_better' ? 'Assistance · lower is better' : 'Added weight · higher is better'].join(' · ');
}
type TargetSelection = Record<string, 'primary' | 'secondary'>;
function targetKey(kind: 'group' | 'muscle', id: string) { return `${kind}:${id}`; }
function targetsFor(exercise: Exercise): TargetSelection { return Object.fromEntries((exercise.exercise_muscles ?? []).flatMap((target) => target.muscles ? [[targetKey('muscle', target.muscles.id), target.role]] : target.muscle_groups ? [[targetKey('group', target.muscle_groups.id), target.role]] : [])); }
function targetRows(exerciseId: string, targets: TargetSelection) { return Object.entries(targets).map(([key, role]) => { const [kind, id] = key.split(':'); return { exercise_id: exerciseId, role, muscle_id: kind === 'muscle' ? id : null, muscle_group_id: kind === 'group' ? id : null }; }); }
function TargetPicker({ muscles, targets, setTargets }: { muscles: Muscle[]; targets: TargetSelection; setTargets: (targets: TargetSelection) => void }) {
  const groups = [...new Map(muscles.flatMap((muscle) => muscle.muscle_groups ? [[muscle.muscle_groups.id, muscle.muscle_groups]] : [])).values()].sort((a, b) => a.position - b.position);
  function choose(key: string, role: 'primary' | 'secondary' | 'none') { const next = { ...targets }; const [kind, id] = key.split(':'); if (role === 'none') delete next[key]; else { if (kind === 'group') muscles.filter((muscle) => muscle.group_id === id).forEach((muscle) => delete next[targetKey('muscle', muscle.id)]); else { const groupId = muscles.find((muscle) => muscle.id === id)?.group_id; if (groupId) delete next[targetKey('group', groupId)]; } if (role === 'primary') Object.keys(next).forEach((entry) => { if (next[entry] === 'primary') next[entry] = 'secondary'; }); next[key] = role; } setTargets(next); }
  const select = (key: string, inherited?: { role: 'primary' | 'secondary'; name: string }) => <select value={inherited ? `inherited-${inherited.role}` : targets[key] ?? 'none'} disabled={Boolean(inherited)} onChange={(event) => choose(key, event.target.value as 'primary' | 'secondary' | 'none')}><option value="none">Not targeted</option><option value="primary">Primary</option><option value="secondary">Secondary</option>{inherited && <option value={`inherited-${inherited.role}`}>{`${inherited.role === 'primary' ? 'Primary' : 'Secondary'} via ${inherited.name}`}</option>}</select>;
  return <div className="target-list">{groups.map((group) => { const groupMuscles = muscles.filter((muscle) => muscle.group_id === group.id); const selectedChildren = groupMuscles.flatMap((muscle) => { const role = targets[targetKey('muscle', muscle.id)]; return role ? [{ name: muscle.name, role }] : []; }); const inherited = selectedChildren.find((target) => target.role === 'primary') ?? selectedChildren[0]; return <div className="target-group" key={group.id}><div className="target-group-row"><b>{group.name}</b>{select(targetKey('group', group.id), targets[targetKey('group', group.id)] ? undefined : inherited)}</div>{groupMuscles.map((muscle) => <div className="target-muscle-row" key={muscle.id}><span>{muscle.name}</span>{select(targetKey('muscle', muscle.id))}</div>)}</div>; })}</div>;
}

export default function GymTracker() {
  const [userId, setUserId] = useState<string | null>(null);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [screen, setScreen] = useState<Screen>('home');
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState<string | null>(null);
  const [exercises, setExercises] = useState<Exercise[]>([]);
  const [muscleGroups, setMuscleGroups] = useState<MuscleGroup[]>([]);
  const [muscles, setMuscles] = useState<Muscle[]>([]);
  const [routines, setRoutines] = useState<Routine[]>([]);
  const [sessions, setSessions] = useState<Workout[]>([]);
  const [activeWorkout, setActiveWorkout] = useState<Workout | null>(null);
  const [installPrompt, setInstallPrompt] = useState<BeforeInstallPromptEvent | null>(null);
  const loadRequest = useRef(0);

  const load = async (id = userId) => {
    if (!supabase || !id) return;
    const request = ++loadRequest.current;
    // Initial auth starts with loading=true. Later saves refresh in the background
    // so a blur on a single input never replaces the whole screen with a spinner.
    const [profileRes, exerciseRes, groupRes, muscleRes, routineRes, sessionRes] = await Promise.all([
      supabase.from('profiles').select('id, display_name, role, default_set_count').eq('id', id).single(),
      supabase.from('exercises').select('id, name, primary_muscle, equipment, weight_direction, created_by, exercise_targets(role, muscles(id, name, group_id, position, muscle_groups(id, name, position)), muscle_groups(id, name, position))').eq('is_retired', false).order('name'),
      supabase.from('muscle_groups').select('id, name, position').order('position'),
      supabase.from('muscles').select('id, name, group_id, position, muscle_groups(id, name, position)').order('position'),
      supabase.from('routines').select('id, name, description, owner_id, copied_from_routine_id, archived_at, profiles!routines_owner_id_fkey(display_name), routine_items(id, exercise_id, position, default_setup_label, exercises(id, name, primary_muscle, equipment, weight_direction, created_by))').order('updated_at', { ascending: false }),
      supabase.from('workout_sessions').select('id, title, started_at, finished_at, notes, session_exercises(id, session_id, exercise_id, position, setup_label, notes, exercises(id, name, primary_muscle, equipment, weight_direction, created_by), sets(id, session_exercise_id, set_number, set_type, reps, weight_kg, note))').eq('owner_id', id).order('started_at', { ascending: false }),
    ]);
    if (request !== loadRequest.current) return;
    if (profileRes.data) setProfile(profileRes.data as Profile);
    if (exerciseRes.data) setExercises((exerciseRes.data as unknown as Array<Exercise & { exercise_targets?: ExerciseTarget[] }>).map(({ exercise_targets, ...exercise }) => ({ ...exercise, exercise_muscles: exercise_targets ?? [] })));
    if (groupRes.data) setMuscleGroups(groupRes.data as MuscleGroup[]);
    if (muscleRes.data) setMuscles(muscleRes.data as unknown as Muscle[]);
    if (routineRes.data) setRoutines(routineRes.data as unknown as Routine[]);
    if (sessionRes.data) {
      const rows = sessionRes.data as unknown as Workout[];
      setSessions(rows);
      setActiveWorkout(rows.find((row) => !row.finished_at) ?? null);
    }
    if (request === loadRequest.current) setLoading(false);
  };

  useEffect(() => {
    if (!supabase) { setLoading(false); return; }
    supabase.auth.getUser().then(({ data }) => { setUserId(data.user?.id ?? null); setUserEmail(data.user?.email ?? null); if (data.user) load(data.user.id); else setLoading(false); });
    const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => {
      setUserId(session?.user.id ?? null);
      setUserEmail(session?.user.email ?? null);
      if (session?.user) load(session.user.id); else { setProfile(null); setUserEmail(null); setLoading(false); }
    });
    return () => listener.subscription.unsubscribe();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const rememberInstallPrompt = (event: Event) => { event.preventDefault(); setInstallPrompt(event as BeforeInstallPromptEvent); };
    window.addEventListener('beforeinstallprompt', rememberInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', rememberInstallPrompt);
  }, []);

  const refresh = async () => { await load(); };
  const notify = (text: string) => { setMessage(text); window.setTimeout(() => setMessage(null), 3500); };
  const installApp = async () => {
    if (installPrompt) {
      await installPrompt.prompt();
      const choice = await installPrompt.userChoice;
      if (choice.outcome === 'accepted') notify('Lift Log was added to your home screen.');
      setInstallPrompt(null);
      return;
    }
    const isAppleMobile = /iPhone|iPad|iPod/i.test(navigator.userAgent);
    notify(isAppleMobile ? 'In Safari, tap Share, then Add to Home Screen.' : 'Use your browser menu and choose Install app or Add to home screen.');
  };

  if (!hasSupabaseConfig) return <SetupNeeded />;
  if (loading) return <div className="loading"><LoaderCircle className="spin" /> Loading your log…</div>;
  if (!userId) return <AuthScreen />;

  const content = (() => {
    if (screen === 'workout') return <WorkoutScreen exercises={exercises} workout={activeWorkout} ownerId={userId} initialSetCount={profile?.default_set_count ?? 3} onChange={refresh} onDone={() => setScreen('history')} onGoRoutines={() => setScreen('routines')} notify={notify} />;
    if (screen === 'routines') return <RoutinesScreen routines={routines} exercises={exercises} ownerId={userId} onChange={refresh} onStart={(routine) => { setScreen('workout'); window.sessionStorage.setItem('start-routine', routine.id); }} notify={notify} />;
    if (screen === 'history') return <HistoryScreen sessions={sessions.filter((item) => item.finished_at)} exercises={exercises} initialSetCount={profile?.default_set_count ?? 3} onChange={refresh} notify={notify} />;
    if (screen === 'progress') return <ProgressScreen sessions={sessions.filter((item) => item.finished_at)} exercises={exercises} />;
    if (screen === 'catalog') return <CatalogScreen exercises={exercises} muscles={muscles} userId={userId} isAdmin={profile?.role === 'admin'} onChange={refresh} notify={notify} />;
    if (screen === 'muscles') return <MuscleCatalogScreen groups={muscleGroups} muscles={muscles} isAdmin={profile?.role === 'admin'} onChange={refresh} notify={notify} />;
    if (screen === 'more') return <MoreScreen canInstall={Boolean(installPrompt)} onInstall={installApp} onNavigate={setScreen} onSignOut={async () => { await supabase!.auth.signOut(); }} />;
    if (screen === 'profile') return <ProfileSettingsScreen profile={profile} email={userEmail} onBack={() => setScreen('more')} onChange={refresh} notify={notify} />;
    return <HomeScreen profile={profile} activeWorkout={activeWorkout} sessions={sessions} onNavigate={setScreen} />;
  })();

  return <main className="app-shell"><header className="topbar"><button className="brand" onClick={() => setScreen('home')}><span className="logo"><Dumbbell size={19}/></span>Lift Log</button><button className="avatar" onClick={() => setScreen('profile')}>{profile?.display_name?.slice(0, 1).toUpperCase() ?? '?'}</button></header>{content}<nav className="bottom-nav">{nav.map(([key, Icon, label]) => <button key={key} className={screen === key ? 'active' : ''} onClick={() => setScreen(key)}><Icon size={19}/><span>{label}</span></button>)}</nav>{message && <div className="toast"><Check size={18}/>{message}</div>}</main>;
}

function SetupNeeded() { return <main className="setup"><div className="brand-mark"><Dumbbell /></div><h1>Lift Log</h1><p>Connect this app to Supabase to begin.</p><ol><li>Create a Supabase project.</li><li>Run the SQL migration in <code>supabase/migrations/001_initial.sql</code>.</li><li>Copy <code>.env.example</code> to <code>.env.local</code> and add the project URL and anon key.</li></ol></main>; }

function AuthScreen() {
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [name, setName] = useState('');
  const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null); const [confirmation, setConfirmation] = useState(false);
  async function submit(event: FormEvent) {
    event.preventDefault(); setBusy(true); setError(null);
    const result = mode === 'login' ? await supabase!.auth.signInWithPassword({ email, password }) : await supabase!.auth.signUp({ email, password, options: { data: { display_name: name } } });
    setBusy(false); if (result.error) return setError(result.error.message); if (mode === 'signup' && !result.data.session) setConfirmation(true);
  }
  return <main className="auth"><div className="auth-card"><div className="brand-mark"><Dumbbell/></div><p className="eyebrow">TRAIN TOGETHER, TRACK YOURSELF</p><h1>{mode === 'login' ? 'Welcome back.' : 'Make your account.'}</h1><p className="muted">{mode === 'login' ? 'Your training history is waiting.' : 'Just the essentials. You can be training in a minute.'}</p>{confirmation ? <div className="notice">Check your email to confirm your account, then sign in.</div> : <form onSubmit={submit}>{mode === 'signup' && <label>Display name<input required maxLength={40} value={name} onChange={(e) => setName(e.target.value)} placeholder="How friends know you"/></label>}<label>Email<input required type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.com"/></label><label>Password<input required minLength={6} type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="At least 6 characters"/></label>{error && <p className="error">{error}</p>}<button className="button primary full" disabled={busy}>{busy && <LoaderCircle className="spin" size={17}/>} {mode === 'login' ? 'Sign in' : 'Create account'}</button></form>}<button className="text-button" onClick={() => { setMode(mode === 'login' ? 'signup' : 'login'); setError(null); setConfirmation(false); }}>{mode === 'login' ? 'New here? Create an account' : 'Already have an account? Sign in'}</button></div></main>;
}

function HomeScreen({ profile, activeWorkout, sessions, onNavigate }: { profile: Profile | null; activeWorkout: Workout | null; sessions: Workout[]; onNavigate: (s: Screen) => void }) {
  const completed = sessions.filter((item) => item.finished_at); const thisWeek = completed.filter((item) => Date.now() - new Date(item.started_at).getTime() < 7 * 86400000);
  return <section className="page home"><p className="eyebrow">{new Intl.DateTimeFormat(undefined, { weekday: 'long' }).format(new Date())}</p><h1>Hey, {profile?.display_name?.split(' ')[0] ?? 'there'}.</h1>{activeWorkout ? <div className="resume-card"><span className="status-dot"/><div><b>Workout in progress</b><small>Started {dateLabel(activeWorkout.started_at)}</small></div><button className="button primary" onClick={() => onNavigate('workout')}>Resume</button></div> : <button className="start-card" onClick={() => onNavigate('workout')}><span><CirclePlus size={25}/></span><div><b>Start a workout</b><small>Log today’s training</small></div><ChevronRight/></button>}<div className="stat-grid"><div><strong>{thisWeek.length}</strong><span>sessions this week</span></div><div><strong>{completed.length}</strong><span>sessions total</span></div></div><button className="progress-quick-card" onClick={() => onNavigate('progress')}><span><BarChart3 size={22}/></span><div><b>Track your progress</b><small>See your best sets and evolution</small></div><ChevronRight/></button><div className="section-heading"><h2>Recent workouts</h2><button className="text-button" onClick={() => onNavigate('history')}>See all</button></div>{completed.slice(0, 3).map((session) => <div className="list-card" key={session.id}><div><b>{session.title || 'Workout'}</b><small>{dateLabel(session.started_at)} · {session.session_exercises?.length ?? 0} exercises</small></div></div>)}{!completed.length && <div className="empty"><Dumbbell/><b>Your first workout starts here.</b><span>Record an exercise, a setup, and your sets.</span></div>}</section>;
}

function WorkoutScreen({ exercises, workout, ownerId, initialSetCount, onChange, onDone, onGoRoutines, notify }: { exercises: Exercise[]; workout: Workout | null; ownerId: string; initialSetCount: number; onChange: () => void; onDone: () => void; onGoRoutines: () => void; notify: (x: string) => void }) {
  const [working, setWorking] = useState(false); const [picker, setPicker] = useState(false); const [editingDetails, setEditingDetails] = useState(false); const [title, setTitle] = useState(workout?.title ?? ''); const [notes, setNotes] = useState(workout?.notes ?? '');
  useEffect(() => { setTitle(workout?.title ?? ''); setNotes(workout?.notes ?? ''); }, [workout?.id, workout?.title, workout?.notes]);
  useEffect(() => {
    // Read within the effect, rather than from a render-time value. React runs
    // effects twice in development, and this consumes the requested routine once.
    const routineId = window.sessionStorage.getItem('start-routine');
    if (!routineId || workout) return;
    window.sessionStorage.removeItem('start-routine');
    void startRoutine(routineId);
  // startRoutine deliberately uses the current screen state; only rerun when an active workout changes.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [workout]);
  async function createWorkout(workoutTitle = title) { const { data, error } = await supabase!.from('workout_sessions').insert({ owner_id: ownerId, title: workoutTitle || null }).select('id, title, started_at, finished_at, notes').single(); if (error) throw error; return data as Workout; }
  async function ensureWorkout() { if (workout) return workout; const created = await createWorkout(); onChange(); return created; }
  async function prefillSets(sessionExerciseIds: string[]) { if (!sessionExerciseIds.length) return; const rows = sessionExerciseIds.flatMap((id) => Array.from({ length: initialSetCount }, (_, index) => ({ session_exercise_id: id, set_number: index + 1, set_type: 'standard', reps: 0, weight_kg: 0 }))); const { error } = await supabase!.from('sets').insert(rows); if (error) throw error; }
  async function startRoutine(routineId: string) { setWorking(true); let fresh: Workout | null = null; const { data: routine, error: routineError } = await supabase!.from('routines').select('name, routine_items(exercise_id, position, default_setup_label)').eq('id', routineId).single(); try { if (routineError) throw routineError; const routineTitle = `Workout - ${routine?.name ?? 'Routine'}`; fresh = await createWorkout(routineTitle); setTitle(routineTitle); const items = (routine?.routine_items ?? []).map((item: { exercise_id: string; position: number; default_setup_label: string | null }) => ({ session_id: fresh!.id, exercise_id: item.exercise_id, position: item.position, setup_label: item.default_setup_label })); if (items.length) { const { data: added, error } = await supabase!.from('session_exercises').insert(items).select('id'); if (error) throw error; await prefillSets((added ?? []).map((item) => item.id)); } onChange(); notify(`Started ${routine?.name ?? 'routine'} with ${initialSetCount} sets per exercise`); } catch (error) { if (fresh) await supabase!.from('workout_sessions').delete().eq('id', fresh.id); notify(errMessage(error)); } finally { setWorking(false); } }
  async function addExercise(exercise: Exercise) { setWorking(true); try { const active = await ensureWorkout(); const position = (active.session_exercises?.length ?? 0) + 1; const { data: added, error } = await supabase!.from('session_exercises').insert({ session_id: active.id, exercise_id: exercise.id, position }).select('id').single(); if (error || !added) throw error ?? new Error('Could not add exercise'); await prefillSets([added.id]); setPicker(false); onChange(); } catch (error) { notify(errMessage(error)); } finally { setWorking(false); } }
  async function saveDetails() { if (!workout) return; setWorking(true); const { error } = await supabase!.from('workout_sessions').update({ title: title || null, notes: notes || null }).eq('id', workout.id); if (error) notify(errMessage(error)); else { await onChange(); setEditingDetails(false); notify('Workout details saved'); } setWorking(false); }
  function cancelDetails() { setTitle(workout?.title ?? ''); setNotes(workout?.notes ?? ''); setEditingDetails(false); }
  async function finish() { if (!workout) return; setWorking(true); const { error: titleError } = await supabase!.from('workout_sessions').update({ title: title || null }).eq('id', workout.id); const { error } = titleError ? { error: titleError } : await supabase!.rpc('finish_workout', { workout_id: workout.id }); if (error) { setWorking(false); notify(errMessage(error)); return; } await onChange(); setWorking(false); notify('Workout finished'); onDone(); }
  async function cancelWorkout() { if (!workout || !window.confirm('Cancel this unfinished workout? Its exercises and sets will be deleted.')) return; setWorking(true); const { error } = await supabase!.from('workout_sessions').delete().eq('id', workout.id); if (error) { setWorking(false); notify(errMessage(error)); return; } await onChange(); setWorking(false); notify('Unfinished workout cancelled'); }
  if (!workout) return <section className="page workout"><p className="eyebrow">READY WHEN YOU ARE</p><h1>Start training</h1><p className="muted">Choose a shared routine or begin with an empty workout.</p><button className="button primary full" disabled={working} onClick={onGoRoutines}>{working ? <LoaderCircle className="spin" size={17}/> : <BookOpen size={17}/>} Start workout from routine</button><button className="button secondary full" disabled={working} onClick={async () => { setWorking(true); try { await ensureWorkout(); } catch (error) { notify(errMessage(error)); } finally { setWorking(false); } }}>Start blank workout</button><DefaultSetCountSetting ownerId={ownerId} initialSetCount={initialSetCount} onChange={onChange} notify={notify}/></section>;
  return <section className="page workout">{editingDetails ? <div className="workout-details-edit"><div className="edit-fields"><input autoFocus value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Workout title"/><textarea value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Workout description or note"/></div><div className="title-actions"><button className="button secondary compact" disabled={working} onClick={cancelDetails}>Cancel</button><button className="button primary compact" disabled={working} onClick={saveDetails}>{working && <LoaderCircle className="spin" size={15}/>} Save</button></div></div> : <div className="workout-title"><div><h1>{title || 'Workout'}</h1><small>Started {dateLabel(workout.started_at)}</small>{workout.notes && <p className="workout-note">{workout.notes}</p>}</div><button className="text-button" onClick={() => setEditingDetails(true)}>Edit</button></div>}<div className="section-heading"><h2>Exercises</h2><button className="button compact" onClick={() => setPicker(true)}><Plus size={17}/> Add</button></div>{(workout.session_exercises ?? []).map((item) => <ExerciseLog key={item.id} item={item} onChange={onChange} notify={notify}/>) }{!(workout.session_exercises?.length) && <div className="empty"><Dumbbell/><b>Add your first exercise</b><span>Choose from the global catalog.</span></div>}<button className="button primary full finish" disabled={working} onClick={finish}><Check size={17}/> Finish workout</button><button className="text-button danger-text cancel-workout" disabled={working} onClick={cancelWorkout}>Cancel unfinished workout</button>{picker && <ExercisePicker exercises={exercises} onChoose={addExercise} onClose={() => setPicker(false)}/>}</section>;
}

function DefaultSetCountSetting({ ownerId, initialSetCount, onChange, notify }: { ownerId: string; initialSetCount: number; onChange: () => void; notify: (x: string) => void }) {
  const [setCount, setSetCount] = useState(String(initialSetCount)); const [saving, setSaving] = useState(false);
  useEffect(() => setSetCount(String(initialSetCount)), [initialSetCount]);
  async function save() { const count = Math.max(1, Math.min(20, Number(setCount) || 3)); setSaving(true); const { error } = await supabase!.from('profiles').update({ default_set_count: count }).eq('id', ownerId); setSaving(false); if (error) notify(error.message); else { setSetCount(String(count)); await onChange(); notify(`Default set count saved: ${count}`); } }
  return <section className="settings-card workout-set-setting"><div><b>Default sets per exercise</b><small>Pre-added when you add an exercise to this workout.</small></div><div className="setting-control"><input aria-label="Default set count" type="number" min="1" max="20" inputMode="numeric" value={setCount} onChange={(e) => setSetCount(e.target.value)}/><button className="button compact primary" disabled={saving} onClick={save}>{saving ? 'Saving' : 'Save'}</button></div></section>;
}

function ExerciseLog({ item, onChange, notify }: { item: SessionExercise; onChange: () => void; notify: (x: string) => void }) {
  const [setup, setSetup] = useState(item.setup_label ?? ''); const [note, setNote] = useState(item.notes ?? ''); const [saving, setSaving] = useState(false);
  async function updateMeta() { const { error } = await supabase!.from('session_exercises').update({ setup_label: setup || null, notes: note || null }).eq('id', item.id); if (error) notify(errMessage(error)); else onChange(); }
  async function addSet() { const next = (item.sets?.length ?? 0) + 1; const last = item.sets?.at(-1); const { error } = await supabase!.from('sets').insert({ session_exercise_id: item.id, set_number: next, set_type: 'standard', reps: last?.reps ?? 10, weight_kg: last?.weight_kg ?? 0 }); if (error) notify(errMessage(error)); else onChange(); }
  async function removeExercise() { if (!window.confirm(`Remove ${item.exercises?.name}?`)) return; const { error } = await supabase!.from('session_exercises').delete().eq('id', item.id); if (error) notify(errMessage(error)); else onChange(); }
  return <article className="exercise-log"><div className="exercise-head"><div><h3>{item.exercises?.name}</h3><input className="setup-input" value={setup} onChange={(e) => setSetup(e.target.value)} onBlur={updateMeta}/></div><button className="icon-button danger" onClick={removeExercise}><Trash2 size={17}/></button></div><div className="set-table"><div className="set-row set-label"><span>SET</span><span>TYPE</span><span>KG</span><span>REPS</span><span/></div>{(item.sets ?? []).map((set) => <SetEditor key={set.id} row={set} onChange={onChange} notify={notify}/>)}</div><button className="add-set" onClick={addSet}><Plus size={16}/> Add set</button><details><summary>Exercise note</summary><textarea value={note} onChange={(e) => setNote(e.target.value)} onBlur={updateMeta} placeholder="Optional note for this exercise"/></details></article>;
}

function SetEditor({ row, onChange, notify }: { row: SetRow; onChange: () => void; notify: (x: string) => void }) {
  const [values, setValues] = useState({ reps: String(row.reps), weight: String(row.weight_kg), type: row.set_type });
  async function save() { const { error } = await supabase!.from('sets').update({ reps: Number(values.reps) || 0, weight_kg: Number(values.weight) || 0, set_type: values.type }).eq('id', row.id); if (error) notify(errMessage(error)); else onChange(); }
  async function remove() { const { error } = await supabase!.from('sets').delete().eq('id', row.id); if (error) notify(errMessage(error)); else onChange(); }
  return <div className="set-row"><span>{row.set_number}</span><select value={values.type} onChange={(e) => setValues({ ...values, type: e.target.value })} onBlur={save}>{setTypes.map((type) => <option key={type} value={type}>{type.replace('_', ' ')}</option>)}</select><input inputMode="decimal" value={values.weight} onChange={(e) => setValues({ ...values, weight: e.target.value })} onBlur={save}/><input inputMode="numeric" value={values.reps} onChange={(e) => setValues({ ...values, reps: e.target.value })} onBlur={save}/><button className="icon-button" onClick={remove}><X size={15}/></button></div>;
}

function RoutinesScreen({ routines, exercises, ownerId, onChange, onStart, notify }: { routines: Routine[]; exercises: Exercise[]; ownerId: string; onChange: () => void; onStart: (r: Routine) => void; notify: (x: string) => void }) {
  const [creating, setCreating] = useState(false); const [editing, setEditing] = useState<Routine | null>(null); const [inspecting, setInspecting] = useState<Routine | null>(null); const mine = routines.filter((r) => r.owner_id === ownerId && !r.archived_at); const shared = routines.filter((r) => r.owner_id !== ownerId && !r.archived_at); const archived = routines.filter((r) => r.owner_id === ownerId && r.archived_at);
  async function copy(routine: Routine) { const { data, error } = await supabase!.from('routines').insert({ owner_id: ownerId, name: `${routine.name} (copy)`, description: routine.description, copied_from_routine_id: routine.id }).select('id').single(); if (error || !data) return notify(error?.message ?? 'Could not copy routine'); const items = (routine.routine_items ?? []).map((item) => ({ routine_id: data.id, exercise_id: item.exercise_id, position: item.position, default_setup_label: item.default_setup_label })); if (items.length) { const { error: itemError } = await supabase!.from('routine_items').insert(items); if (itemError) return notify(itemError.message); } onChange(); notify('Routine copied to My routines'); }
  async function deleteRoutine(routine: Routine) { if (!window.confirm(`Delete “${routine.name}”? This only removes the template, never past workouts.`)) return; const { error } = await supabase!.from('routines').delete().eq('id', routine.id); if (error) notify(error.message); else { onChange(); notify('Routine deleted'); } }
  async function archiveRoutine(routine: Routine) { if (!window.confirm(`Archive “${routine.name}”? You can still inspect it later, but it will no longer appear in active routines.`)) return; const { error } = await supabase!.from('routines').update({ archived_at: new Date().toISOString() }).eq('id', routine.id); if (error) notify(error.message); else { onChange(); notify('Routine archived'); } }
  return <section className="page"><div className="section-heading"><div><p className="eyebrow">SHARED LIBRARY</p><h1>Routines</h1></div><button className="button compact" onClick={() => setCreating(true)}><Plus size={17}/> New</button></div><h2>My routines</h2>{mine.length ? mine.map((routine) => <RoutineCard key={routine.id} routine={routine} own onStart={() => onStart(routine)} onEdit={() => setEditing(routine)} onArchive={() => archiveRoutine(routine)} onDelete={() => deleteRoutine(routine)}/>) : <p className="muted">No routines yet. Create one or make a copy below.</p>}<h2 className="spaced">Browse routines</h2>{shared.length ? shared.map((routine) => <RoutineCard key={routine.id} routine={routine} onStart={() => onStart(routine)} onCopy={() => copy(routine)}/>) : <p className="muted">Your friends’ routines will appear here.</p>}{archived.length > 0 && <><h2 className="spaced">Archived routines</h2>{archived.map((routine) => <RoutineCard key={routine.id} routine={routine} own archived onInspect={() => setInspecting(routine)} onDelete={() => deleteRoutine(routine)}/>)}</>}{creating && <RoutineForm exercises={exercises} ownerId={ownerId} onClose={() => setCreating(false)} onChange={onChange} notify={notify}/>} {editing && <RoutineForm routine={editing} exercises={exercises} ownerId={ownerId} onClose={() => setEditing(null)} onChange={onChange} notify={notify}/>} {inspecting && <RoutineInspector routine={inspecting} onClose={() => setInspecting(null)}/>}</section>;
}

function RoutineCard({ routine, own, archived, onStart, onCopy, onEdit, onArchive, onInspect, onDelete }: { routine: Routine; own?: boolean; archived?: boolean; onStart?: () => void; onCopy?: () => void; onEdit?: () => void; onArchive?: () => void; onInspect?: () => void; onDelete?: () => void }) { return <article className={`routine-card${archived ? ' archived-routine' : ''}`}><div><p className="eyebrow">{archived ? 'ARCHIVED' : own ? 'YOUR ROUTINE' : `BY ${routine.profiles?.display_name ?? 'A MEMBER'}`}</p><h3>{routine.name}</h3>{routine.description && <p className="muted">{routine.description}</p>}<div className="chips">{(routine.routine_items ?? []).slice(0, 4).map((item) => <span key={item.id}>{item.exercises?.name}</span>)}</div></div><div className="card-actions">{onStart && <button className="button compact" onClick={onStart}><Play size={15}/> Start</button>}{onCopy && <button className="button secondary compact" onClick={onCopy}>Copy</button>}{onEdit && <button className="button secondary compact" onClick={onEdit}>Edit</button>}{onArchive && <button className="button secondary compact" onClick={onArchive}>Archive</button>}{onInspect && <button className="button secondary compact" onClick={onInspect}>Inspect</button>}{onDelete && <button className="text-button danger-text" onClick={onDelete}>Delete</button>}</div></article>; }

function RoutineInspector({ routine, onClose }: { routine: Routine; onClose: () => void }) { return <Modal title="Archived routine" onClose={onClose}><p className="eyebrow">READ-ONLY</p><h3 className="inspector-title">{routine.name}</h3>{routine.description && <p className="muted inspector-description">{routine.description}</p>}<h2>Exercises</h2><div className="inspector-items">{(routine.routine_items ?? []).sort((a, b) => a.position - b.position).map((item, index) => <div key={item.id}><span>{index + 1}</span><div><b>{item.exercises?.name}</b>{item.default_setup_label && <small>{item.default_setup_label}</small>}</div></div>)}</div>{!(routine.routine_items?.length) && <p className="muted">This routine has no exercises.</p>}<button className="button secondary full" onClick={onClose}>Close</button></Modal>; }

function RoutineForm({ routine, exercises, ownerId, onClose, onChange, notify }: { routine?: Routine; exercises: Exercise[]; ownerId: string; onClose: () => void; onChange: () => void; notify: (x: string) => void }) { const [name, setName] = useState(routine?.name ?? ''); const [description, setDescription] = useState(routine?.description ?? ''); const [items, setItems] = useState<{ exercise_id: string; setup: string }[]>(() => (routine?.routine_items ?? []).map((item) => ({ exercise_id: item.exercise_id, setup: item.default_setup_label ?? '' }))); const [selected, setSelected] = useState(''); const [busy, setBusy] = useState(false); async function save() { if (!name.trim()) return; setBusy(true); let routineId = routine?.id; if (routineId) { const { error } = await supabase!.from('routines').update({ name: name.trim(), description: description || null }).eq('id', routineId); if (error) { setBusy(false); return notify(error.message); } const { error: deleteError } = await supabase!.from('routine_items').delete().eq('routine_id', routineId); if (deleteError) { setBusy(false); return notify(deleteError.message); } } else { const { data, error } = await supabase!.from('routines').insert({ owner_id: ownerId, name: name.trim(), description: description || null }).select('id').single(); if (error || !data) { setBusy(false); return notify(error?.message ?? 'Could not create routine'); } routineId = data.id; } if (items.length) { const { error: itemError } = await supabase!.from('routine_items').insert(items.map((item, i) => ({ routine_id: routineId!, exercise_id: item.exercise_id, position: i + 1, default_setup_label: item.setup || null }))); if (itemError) { setBusy(false); return notify(itemError.message); } } setBusy(false); onChange(); onClose(); notify(routine ? 'Routine updated' : 'Shared routine created'); } return <Modal title={routine ? 'Edit routine' : 'New shared routine'} onClose={onClose}><label>Name<input autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Upper body"/></label><label>Description<textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Optional guidance"/></label><div className="inline-add"><select value={selected} onChange={(e) => setSelected(e.target.value)}><option value="">Add exercise…</option>{exercises.map((x) => <option key={x.id} value={x.id}>{x.name}</option>)}</select><button className="button compact" onClick={() => { if (selected) { setItems([...items, { exercise_id: selected, setup: '' }]); setSelected(''); } }}>Add</button></div>{items.map((item, i) => <div className="routine-item-edit" key={`${item.exercise_id}-${i}`}><b>{exercises.find((x) => x.id === item.exercise_id)?.name}</b><input value={item.setup} onChange={(e) => setItems(items.map((x, index) => index === i ? { ...x, setup: e.target.value } : x))} placeholder="Default setup (optional)"/><button className="icon-button" onClick={() => setItems(items.filter((_, index) => index !== i))}><X size={16}/></button></div>)}<button className="button primary full" disabled={busy} onClick={save}><Save size={16}/> {routine ? 'Save routine' : 'Publish routine'}</button></Modal>; }

function HistoryScreen({ sessions, exercises, initialSetCount, onChange, notify }: { sessions: Workout[]; exercises: Exercise[]; initialSetCount: number; onChange: () => Promise<void>; notify: (x: string) => void }) { const [selected, setSelected] = useState<Workout | null>(null); return <section className="page"><p className="eyebrow">YOUR RECORD</p><h1>History</h1>{sessions.length ? sessions.map((session) => <article className="history-card" key={session.id}><div><div><h3>{session.title || 'Workout'}</h3><p>{dateLabel(session.started_at)} · {session.session_exercises?.length ?? 0} exercises</p></div><button className="text-button" onClick={() => setSelected(session)}>Edit</button></div><div className="history-exercises">{(session.session_exercises ?? []).map((item) => <span key={item.id}><b>{item.exercises?.name}</b><small>{bestSetLabel(item.sets, item.exercises?.weight_direction)}</small></span>)}</div>{session.notes && <div className="history-description"><span>Description</span><p>{session.notes}</p></div>}</article>) : <div className="empty"><History/><b>Nothing recorded yet.</b><span>Finished workouts will live here.</span></div>}{selected && <FinishedWorkoutEditor workout={selected} exercises={exercises} initialSetCount={initialSetCount} onClose={() => setSelected(null)} onChange={onChange} notify={notify}/>}</section>; }

function FinishedWorkoutEditor({ workout, exercises, initialSetCount, onClose, onChange, notify }: { workout: Workout; exercises: Exercise[]; initialSetCount: number; onClose: () => void; onChange: () => Promise<void>; notify: (x: string) => void }) {
  const [title, setTitle] = useState(workout.title ?? ''); const [notes, setNotes] = useState(workout.notes ?? ''); const [picker, setPicker] = useState(false); const [busy, setBusy] = useState(false);
  async function saveDetails() { setBusy(true); const { error } = await supabase!.from('workout_sessions').update({ title: title || null, notes: notes || null }).eq('id', workout.id); setBusy(false); if (error) notify(error.message); else { onChange(); notify('Workout details saved'); } }
  async function addExercise(exercise: Exercise) { const { data: existing } = await supabase!.from('session_exercises').select('position').eq('session_id', workout.id).order('position', { ascending: false }).limit(1); const position = (existing?.[0]?.position ?? 0) + 1; setBusy(true); const { data, error } = await supabase!.from('session_exercises').insert({ session_id: workout.id, exercise_id: exercise.id, position }).select('id').single(); if (!error && data) { const sets = Array.from({ length: initialSetCount }, (_, index) => ({ session_exercise_id: data.id, set_number: index + 1, set_type: 'standard', reps: 0, weight_kg: 0 })); const { error: setError } = await supabase!.from('sets').insert(sets); if (setError) notify(setError.message); } setBusy(false); if (error) notify(error.message); else { setPicker(false); onChange(); notify('Exercise added'); } }
  async function deleteWorkout() { if (!window.confirm(`Delete ${workout.title || 'this workout'} permanently? This cannot be undone.`)) return; setBusy(true); const { error } = await supabase!.from('workout_sessions').delete().eq('id', workout.id); if (error) { setBusy(false); notify(error.message); return; } await onChange(); setBusy(false); onClose(); notify('Workout deleted'); }
  return <Modal title="Edit finished workout" onClose={onClose}><p className="muted">{dateLabel(workout.started_at)}</p><label>Workout title<input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Workout title"/></label><label>Workout note<textarea value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Optional note for the whole workout"/></label><button className="button secondary full" disabled={busy} onClick={saveDetails}><Save size={16}/> Save workout details</button><div className="section-heading"><h2>Exercises</h2><button className="button compact" onClick={() => setPicker(true)}><Plus size={16}/> Add</button></div>{(workout.session_exercises ?? []).map((item) => <ExerciseLog key={item.id} item={item} onChange={onChange} notify={notify}/>)}<button className="text-button danger-text delete-workout" disabled={busy} onClick={deleteWorkout}><Trash2 size={15}/> Delete workout permanently</button>{picker && <ExercisePicker exercises={exercises} onChoose={addExercise} onClose={() => setPicker(false)}/>}</Modal>;
}

function ProgressScreen({ sessions, exercises }: { sessions: Workout[]; exercises: Exercise[] }) {
  const [exerciseId, setExerciseId] = useState('');
  const selectedExercise = exercises.find((exercise) => exercise.id === exerciseId);
  const direction = selectedExercise?.weight_direction ?? 'higher_is_better';
  const data = useMemo(() => sessions.flatMap((session) => (session.session_exercises ?? []).filter((item) => !exerciseId || item.exercise_id === exerciseId).flatMap((item) => completedSets(item.sets).map((set) => ({ ...set, date: session.started_at, exercise: item.exercises?.name ?? '', direction: (item.exercises?.weight_direction ?? 'higher_is_better') as WeightDirection })))), [sessions, exerciseId]);
  const best = selectedExercise ? bestWeight(data, direction) : null;
  const chartData = useMemo(() => Object.values(data.reduce<Record<string, { label: string; timestamp: number; bestWeight: number }>>((acc, set) => { const key = new Date(set.date).toISOString().slice(0, 10); const current = acc[key] ?? { label: dateLabel(set.date), timestamp: new Date(set.date).getTime(), bestWeight: Number(set.weight_kg) }; current.bestWeight = direction === 'lower_is_better' ? Math.min(current.bestWeight, Number(set.weight_kg)) : Math.max(current.bestWeight, Number(set.weight_kg)); acc[key] = current; return acc; }, {})).sort((a, b) => a.timestamp - b.timestamp), [data, direction]);
  const isAssistance = direction === 'lower_is_better';
  const primarySetBreakdown = useMemo(() => {
    const totals = new Map<string, { name: string; primary: number; secondary: number }>();
    sessions.forEach((session) => (session.session_exercises ?? []).forEach((item) => {
      const completed = completedSets(item.sets).length;
      if (!completed) return;
      const exercise = exercises.find((entry) => entry.id === item.exercise_id);
      (exercise?.exercise_muscles ?? []).forEach((target) => {
        const group = target.muscle_groups ?? target.muscles?.muscle_groups;
        if (!group) return;
        const groupKey = `group-${group.id}`;
        const groupTotal = totals.get(groupKey) ?? { name: group.name, primary: 0, secondary: 0 };
        groupTotal[target.role] += completed; totals.set(groupKey, groupTotal);
      });
    }));
    return [...totals.entries()].filter(([key]) => key.startsWith('group-')).map(([, value]) => value).sort((a, b) => (b.primary + b.secondary) - (a.primary + a.secondary) || a.name.localeCompare(b.name));
  }, [sessions, exercises]);
  return <section className="page"><p className="eyebrow">PRIVATE TO YOU</p><h1>Progress</h1>{primarySetBreakdown.length > 0 && <><h2>Muscle work</h2><p className="progress-hint">Completed sets attributed to each muscle group.</p><div className="muscle-progress-list">{primarySetBreakdown.map((item) => <div key={item.name}><b>{item.name}</b><span>{[item.primary && `${item.primary} sets primary`, item.secondary && `${item.secondary} sets secondary`].filter(Boolean).join(' + ')}</span></div>)}</div></>}<label>Exercise<select value={exerciseId} onChange={(e) => setExerciseId(e.target.value)}><option value="">All exercises</option>{exercises.map((x) => <option key={x.id} value={x.id}>{x.name}</option>)}</select></label>{!selectedExercise ? <div className="empty"><BarChart3/><b>Select an exercise to see its comparable best-set chart.</b></div> : <><p className="progress-hint">{isAssistance ? 'Less assistance is better.' : 'More added weight is better.'}</p><div className="stat-grid"><div><strong>{best ?? '—'}</strong><span>{isAssistance ? 'lowest assistance (kg)' : 'best weight (kg)'}</span></div><div><strong>{data.length}</strong><span>completed sets logged</span></div></div>{chartData.length > 1 && <><h2>{isAssistance ? 'Assistance over time' : 'Best weight over time'}</h2><div className="chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={chartData} margin={{ top: 10, right: 10, left: -25, bottom: 0 }}><XAxis dataKey="label" tick={{ fill: '#9aa89e', fontSize: 10 }} axisLine={false} tickLine={false}/><YAxis reversed={isAssistance} tick={{ fill: '#9aa89e', fontSize: 10 }} axisLine={false} tickLine={false}/><Tooltip contentStyle={{ background: '#202a22', border: '1px solid #324036', borderRadius: 8 }} labelStyle={{ color: '#e9efe8' }} formatter={(value) => [`${value} kg${isAssistance ? ' assistance' : ''}`, isAssistance ? 'Lowest assistance' : 'Best weight']}/><Line type="monotone" dataKey="bestWeight" stroke="#b7f34a" strokeWidth={3} dot={{ fill: '#b7f34a', r: 3 }}/></LineChart></ResponsiveContainer></div></>}</>}<SetHistory data={data}/></section>;
}

function SetHistory({ data }: { data: Array<SetRow & { date: string; exercise: string; direction: WeightDirection }> }) {
  return <><h2>Set history</h2>{data.length ? <div className="history-table">{[...data].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map((set) => <div key={set.id}><span>{dateLabel(set.date)}</span><b>{set.exercise}</b><span>{set.weight_kg} kg{set.direction === 'lower_is_better' ? ' assistance' : ''} · {set.reps} reps</span><em>{set.set_type.replace('_', ' ')}</em></div>)}</div> : <div className="empty"><BarChart3/><b>Log some completed sets to see progress.</b></div>}</>;
}

function CatalogScreen({ exercises, muscles, userId, isAdmin, onChange, notify }: { exercises: Exercise[]; muscles: Muscle[]; userId: string; isAdmin: boolean; onChange: () => void; notify: (x: string) => void }) {
  const [adding, setAdding] = useState(false); const [query, setQuery] = useState(''); const [suggestFor, setSuggestFor] = useState<Exercise | null>(null); const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  const visible = exercises.filter((x) => x.name.toLowerCase().includes(query.toLowerCase()));
  const loadSuggestions = async () => { if (!isAdmin) return; const { data } = await supabase!.from('exercise_suggestions').select('id, suggestion, status, exercises(name), profiles!exercise_suggestions_author_id_fkey(display_name)').eq('status', 'pending').order('created_at'); if (data) setSuggestions(data as unknown as Suggestion[]); };
  useEffect(() => { void loadSuggestions(); // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isAdmin]);
  return <section className="page"><div className="section-heading"><div><p className="eyebrow">SHARED WITH THE APP</p><h1>Exercise catalog</h1></div><button className="button compact" onClick={() => setAdding(true)}><Plus size={17}/> Add</button></div>{isAdmin && suggestions.length > 0 && <div className="suggestion-panel"><p className="eyebrow">ADMIN QUEUE</p><h2>Correction suggestions</h2>{suggestions.map((suggestion) => <div className="suggestion" key={suggestion.id}><div><b>{suggestion.exercises?.name}</b><small>{suggestion.profiles?.display_name ?? 'Member'}: {suggestion.suggestion}</small></div><div><button className="text-button" onClick={async () => { await supabase!.from('exercise_suggestions').update({ status: 'accepted' }).eq('id', suggestion.id); await loadSuggestions(); notify('Marked accepted — edit the exercise details as needed.'); }}>Accept</button><button className="text-button danger-text" onClick={async () => { await supabase!.from('exercise_suggestions').update({ status: 'dismissed' }).eq('id', suggestion.id); await loadSuggestions(); notify('Suggestion dismissed'); }}>Dismiss</button></div></div>)}</div>}<input className="catalog-search" placeholder="Search exercises" value={query} onChange={(e) => setQuery(e.target.value)}/><div className="catalog-list">{visible.map((exercise) => <div key={exercise.id}><div><b>{exercise.name}</b><small>{exerciseDetails(exercise)}</small></div><div className="catalog-actions">{!isAdmin && <button className="text-button" onClick={() => setSuggestFor(exercise)}>Suggest fix</button>}{(isAdmin || exercise.created_by === userId) && <ExerciseTargetsButton exercise={exercise} muscles={muscles} onChange={onChange} notify={notify}/>} {isAdmin && <AdminRetire exercise={exercise} muscles={muscles} onChange={onChange} notify={notify}/>}</div></div>)}</div>{adding && <ExerciseForm muscles={muscles} onClose={() => setAdding(false)} onChange={onChange} notify={notify}/>} {suggestFor && <SuggestionForm exercise={suggestFor} onClose={() => setSuggestFor(null)} notify={notify}/>}</section>;
}

function ExerciseForm({ muscles, onClose, onChange, notify }: { muscles: Muscle[]; onClose: () => void; onChange: () => void; notify: (x: string) => void }) { const [name, setName] = useState(''); const [equipment, setEquipment] = useState(''); const [direction, setDirection] = useState<WeightDirection>('higher_is_better'); const [targets, setTargets] = useState<TargetSelection>({}); async function save() { const { data, error } = await supabase!.from('exercises').insert({ name: name.trim(), equipment: equipment || null, weight_direction: direction }).select('id').single(); if (error || !data) return notify(error?.message ?? 'Could not add exercise'); const { error: targetError } = await supabase!.from('exercise_targets').insert(targetRows(data.id, targets)); if (targetError) return notify(targetError.message); onChange(); onClose(); notify('Exercise added to the shared catalog'); } return <Modal title="Add an exercise" onClose={onClose}><label>Name<input autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Cable triceps extension"/></label><label>Muscle targets<small>Select a group or a specific muscle. Choose exactly one primary target; any others are secondary.</small></label><TargetPicker muscles={muscles} targets={targets} setTargets={setTargets}/><label>Equipment / machine<input value={equipment} onChange={(e) => setEquipment(e.target.value)} placeholder="e.g. Cable station"/></label><label>Weight meaning<select value={direction} onChange={(e) => setDirection(e.target.value as WeightDirection)}><option value="higher_is_better">Added weight — higher is better</option><option value="lower_is_better">Assistance — lower is better</option></select></label><button className="button primary full" disabled={!name.trim() || Object.values(targets).filter((role) => role === 'primary').length !== 1} onClick={save}>Add exercise</button></Modal>; }
function ExerciseTargetsButton({ exercise, muscles, onChange, notify }: { exercise: Exercise; muscles: Muscle[]; onChange: () => void; notify: (x: string) => void }) { const [editing, setEditing] = useState(false); return <>{!editing && <button className="text-button" onClick={() => setEditing(true)}>Targets</button>}{editing && <ExerciseTargetsForm exercise={exercise} muscles={muscles} onClose={() => setEditing(false)} onChange={onChange} notify={notify}/>}</>; }
function ExerciseTargetsForm({ exercise, muscles, onClose, onChange, notify }: { exercise: Exercise; muscles: Muscle[]; onClose: () => void; onChange: () => void; notify: (x: string) => void }) { const [targets, setTargets] = useState<TargetSelection>(() => targetsFor(exercise)); async function save() { const { error: removeError } = await supabase!.from('exercise_targets').delete().eq('exercise_id', exercise.id); if (removeError) return notify(removeError.message); const { error } = await supabase!.from('exercise_targets').insert(targetRows(exercise.id, targets)); if (error) return notify(error.message); await onChange(); onClose(); notify('Muscle targets saved'); } return <Modal title={`Muscle targets: ${exercise.name}`} onClose={onClose}><p className="muted">Select a group or a specific muscle. Choose exactly one primary target; any others are secondary.</p><TargetPicker muscles={muscles} targets={targets} setTargets={setTargets}/><button className="button primary full" disabled={Object.values(targets).filter((role) => role === 'primary').length !== 1} onClick={save}>Save targets</button></Modal>; }
function SuggestionForm({ exercise, onClose, notify }: { exercise: Exercise; onClose: () => void; notify: (x: string) => void }) { const [text, setText] = useState(''); async function save() { const { error } = await supabase!.from('exercise_suggestions').insert({ exercise_id: exercise.id, suggestion: text.trim() }); if (error) notify(error.message); else { onClose(); notify('Correction sent to the admin'); } } return <Modal title={`Suggest a correction`} onClose={onClose}><p className="muted">For {exercise.name}</p><label>What should change?<textarea autoFocus value={text} onChange={(e) => setText(e.target.value)} placeholder="For example: the machine name should be…"/></label><button className="button primary full" disabled={text.trim().length < 3} onClick={save}>Send suggestion</button></Modal>; }

function AdminRetire({ exercise, muscles, onChange, notify }: { exercise: Exercise; muscles: Muscle[]; onChange: () => void; notify: (x: string) => void }) { const [editing, setEditing] = useState(false); async function retire() { if (!window.confirm(`Retire ${exercise.name}? It will remain in workout history.`)) return; const { error } = await supabase!.from('exercises').update({ is_retired: true }).eq('id', exercise.id); if (error) notify(error.message); else { onChange(); notify('Exercise retired'); } } return <><button className="text-button" onClick={() => setEditing(true)}>Edit</button><button className="text-button danger-text" onClick={retire}>Retire</button>{editing && <AdminExerciseForm exercise={exercise} muscles={muscles} onClose={() => setEditing(false)} onChange={onChange} notify={notify}/>}</>; }
function AdminExerciseForm({ exercise, muscles, onClose, onChange, notify }: { exercise: Exercise; muscles: Muscle[]; onClose: () => void; onChange: () => void; notify: (x: string) => void }) {
  const [name, setName] = useState(exercise.name); const [equipment, setEquipment] = useState(exercise.equipment ?? ''); const [direction, setDirection] = useState<WeightDirection>(exercise.weight_direction);
  const [targets, setTargets] = useState<TargetSelection>(() => targetsFor(exercise));
  async function save() { const { error } = await supabase!.from('exercises').update({ name: name.trim(), equipment: equipment || null, weight_direction: direction }).eq('id', exercise.id); if (error) return notify(error.message); const { error: removeError } = await supabase!.from('exercise_targets').delete().eq('exercise_id', exercise.id); if (removeError) return notify(removeError.message); const { error: targetsError } = await supabase!.from('exercise_targets').insert(targetRows(exercise.id, targets)); if (targetsError) return notify(targetsError.message); onChange(); onClose(); notify('Exercise updated'); }
  return <Modal title="Edit exercise" onClose={onClose}><label>Name<input autoFocus value={name} onChange={(e) => setName(e.target.value)}/></label><label>Targets<small>Select a group or a specific muscle. Choose exactly one primary target; any others are secondary.</small></label><TargetPicker muscles={muscles} targets={targets} setTargets={setTargets}/><label>Equipment / machine<input value={equipment} onChange={(e) => setEquipment(e.target.value)}/></label><label>Weight meaning<select value={direction} onChange={(e) => setDirection(e.target.value as WeightDirection)}><option value="higher_is_better">Added weight — higher is better</option><option value="lower_is_better">Assistance — lower is better</option></select></label><button className="button primary full" disabled={!name.trim() || Object.values(targets).filter((role) => role === 'primary').length !== 1} onClick={save}>Save changes</button></Modal>;
}

function MuscleCatalogScreen({ groups, muscles, isAdmin, onChange, notify }: { groups: MuscleGroup[]; muscles: Muscle[]; isAdmin: boolean; onChange: () => void; notify: (x: string) => void }) {
  const [adding, setAdding] = useState(false); const [suggesting, setSuggesting] = useState<Muscle | 'addition' | null>(null); const [suggestions, setSuggestions] = useState<Array<{ id: string; suggestion: string; muscles?: { name: string } | null; profiles?: { display_name: string | null } | null }>>([]);
  const loadSuggestions = async () => { if (!isAdmin) return; const { data } = await supabase!.from('muscle_suggestions').select('id, suggestion, muscles(name), profiles!muscle_suggestions_author_id_fkey(display_name)').eq('status', 'pending').order('created_at'); if (data) setSuggestions(data as unknown as typeof suggestions); };
  useEffect(() => { void loadSuggestions(); // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isAdmin]);
  async function editMuscle(muscle: Muscle) { const name = window.prompt('Muscle / region name', muscle.name)?.trim(); if (!name || name === muscle.name) return; const { error } = await supabase!.from('muscles').update({ name }).eq('id', muscle.id); if (error) notify(error.message); else { await onChange(); notify('Muscle updated'); } }
  async function deleteMuscle(muscle: Muscle) { if (!window.confirm(`Delete ${muscle.name}? Exercises using it must be updated first.`)) return; const { error } = await supabase!.from('muscles').delete().eq('id', muscle.id); if (error) notify(error.message); else { await onChange(); notify('Muscle deleted'); } }
  return <section className="page"><div className="section-heading"><div><p className="eyebrow">SHARED WITH THE APP</p><h1>Muscle catalog</h1></div>{isAdmin && <button className="button compact" onClick={() => setAdding(true)}><Plus size={17}/> Add</button>}</div><p className="muted">Exercises have one primary target and can include secondary targets.</p>{isAdmin && suggestions.length > 0 && <div className="suggestion-panel"><p className="eyebrow">ADMIN QUEUE</p><h2>Muscle suggestions</h2>{suggestions.map((suggestion) => <div className="suggestion" key={suggestion.id}><div><b>{suggestion.muscles?.name ?? 'New catalogue item'}</b><small>{suggestion.profiles?.display_name ?? 'Member'}: {suggestion.suggestion}</small></div><div><button className="text-button" onClick={async () => { await supabase!.from('muscle_suggestions').update({ status: 'accepted' }).eq('id', suggestion.id); await loadSuggestions(); notify('Marked accepted'); }}>Accept</button><button className="text-button danger-text" onClick={async () => { await supabase!.from('muscle_suggestions').update({ status: 'dismissed' }).eq('id', suggestion.id); await loadSuggestions(); notify('Suggestion dismissed'); }}>Dismiss</button></div></div>)}</div>}{groups.map((group) => <section className="muscle-group" key={group.id}><h2>{group.name}</h2>{muscles.filter((muscle) => muscle.group_id === group.id).map((muscle) => <div className="muscle-row" key={muscle.id}><span>{muscle.name}</span>{isAdmin ? <span className="muscle-actions"><button className="text-button" onClick={() => editMuscle(muscle)}>Edit</button><button className="text-button danger-text" onClick={() => deleteMuscle(muscle)}>Delete</button></span> : <button className="text-button" onClick={() => setSuggesting(muscle)}>Suggest fix</button>}</div>)}</section>)}{!isAdmin && <button className="button secondary full" onClick={() => setSuggesting('addition')}>Suggest an addition</button>}{adding && <MuscleForm groups={groups} onClose={() => setAdding(false)} onChange={onChange} notify={notify}/>} {suggesting && <MuscleSuggestionForm muscle={suggesting === 'addition' ? undefined : suggesting} onClose={() => setSuggesting(null)} notify={notify}/>}</section>;
}

function MuscleForm({ groups, onClose, onChange, notify }: { groups: MuscleGroup[]; onClose: () => void; onChange: () => void; notify: (x: string) => void }) { const [name, setName] = useState(''); const [groupId, setGroupId] = useState(groups[0]?.id ?? ''); const [newGroup, setNewGroup] = useState(''); async function save() { let targetGroupId = groupId; if (newGroup.trim()) { const { data, error } = await supabase!.from('muscle_groups').insert({ name: newGroup.trim() }).select('id').single(); if (error || !data) return notify(error?.message ?? 'Could not create muscle group'); targetGroupId = data.id; } const { error } = await supabase!.from('muscles').insert({ name: name.trim(), group_id: targetGroupId }); if (error) notify(error.message); else { await onChange(); onClose(); notify('Muscle added to the catalog'); } } return <Modal title="Add muscle" onClose={onClose}><label>Muscle / region<input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder="e.g. Serratus anterior"/></label><label>Group<select value={groupId} disabled={Boolean(newGroup.trim())} onChange={(event) => setGroupId(event.target.value)}>{groups.map((group) => <option key={group.id} value={group.id}>{group.name}</option>)}</select></label><label>Or create a new group<input value={newGroup} onChange={(event) => setNewGroup(event.target.value)} placeholder="Optional"/></label><button className="button primary full" disabled={!name.trim() || (!groupId && !newGroup.trim())} onClick={save}>Add muscle</button></Modal>; }
function MuscleSuggestionForm({ muscle, onClose, notify }: { muscle?: Muscle | null; onClose: () => void; notify: (x: string) => void }) { const [text, setText] = useState(''); async function save() { const { error } = await supabase!.from('muscle_suggestions').insert({ muscle_id: muscle?.id ?? null, suggestion: text.trim() }); if (error) notify(error.message); else { onClose(); notify('Suggestion sent to the admin'); } } return <Modal title={muscle ? 'Suggest a correction' : 'Suggest a muscle or group'} onClose={onClose}><p className="muted">{muscle ? `For ${muscle.name}` : 'Tell the admin what should be added.'}</p><label>Suggestion<textarea autoFocus value={text} onChange={(event) => setText(event.target.value)} placeholder={muscle ? 'What should change?' : 'e.g. Add serratus anterior under Core'}/></label><button className="button primary full" disabled={text.trim().length < 3} onClick={save}>Send suggestion</button></Modal>; }

function MoreScreen({ canInstall, onInstall, onNavigate, onSignOut }: { canInstall: boolean; onInstall: () => void; onNavigate: (s: Screen) => void; onSignOut: () => void }) { return <section className="page more-page"><p className="eyebrow">ACCOUNT</p><h1>More</h1><button className="settings-row" onClick={() => onNavigate('progress')}><BarChart3/><span>Progress</span><ChevronRight/></button><button className="settings-row" onClick={() => onNavigate('catalog')}><Database/><span>Exercise catalog</span><ChevronRight/></button><button className="settings-row" onClick={() => onNavigate('muscles')}><Bone/><span>Muscle catalog</span><ChevronRight/></button><button className="settings-row" onClick={() => onNavigate('profile')}><Settings/><span>Profile settings</span><ChevronRight/></button><div className="more-footer"><button className="settings-row" onClick={onInstall}><Download/><span>{canInstall ? 'Install Lift Log' : 'Add Lift Log to your phone'}</span><Info/></button><button className="settings-row logout" onClick={onSignOut}><LogOut/><span>Sign out</span></button></div></section>; }

function ProfileSettingsScreen({ profile, email, onBack, onChange, notify }: { profile: Profile | null; email: string | null; onBack: () => void; onChange: () => void; notify: (x: string) => void }) { const [name, setName] = useState(profile?.display_name ?? ''); const [saving, setSaving] = useState(false); useEffect(() => setName(profile?.display_name ?? ''), [profile?.display_name]); async function save() { if (!profile || !name.trim()) return; setSaving(true); const { error } = await supabase!.from('profiles').update({ display_name: name.trim() }).eq('id', profile.id); setSaving(false); if (error) notify(error.message); else { await onChange(); notify('Profile saved'); } } return <section className="page"><button className="text-button profile-back" onClick={onBack}>Back to More</button><p className="eyebrow">ACCOUNT</p><h1>Profile settings</h1><label>Display name<input value={name} onChange={(event) => setName(event.target.value)} maxLength={40} placeholder="Your name"/></label><label>Email<input value={email ?? ''} readOnly aria-readonly="true"/></label><p className="muted profile-email-note">Your email is used for sign-in and cannot be changed here.</p><button className="button primary full" disabled={saving || !name.trim()} onClick={save}>{saving && <LoaderCircle className="spin" size={16}/>} Save profile</button></section>; }

function ExercisePicker({ exercises, onChoose, onClose }: { exercises: Exercise[]; onChoose: (x: Exercise) => void; onClose: () => void }) { const [query, setQuery] = useState(''); return <Modal title="Add exercise" onClose={onClose}><input autoFocus placeholder="Search catalog" value={query} onChange={(e) => setQuery(e.target.value)}/><div className="picker-list">{exercises.filter((x) => x.name.toLowerCase().includes(query.toLowerCase())).map((exercise) => <button key={exercise.id} onClick={() => onChoose(exercise)}><div><b>{exercise.name}</b><small>{[exercise.primary_muscle, exercise.equipment].filter(Boolean).join(' · ')}</small></div><Plus size={18}/></button>)}</div></Modal>; }
function Modal({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) { return <div className="modal-backdrop"><section className="modal"><div className="modal-head"><h2>{title}</h2><button className="icon-button" onClick={onClose}><X/></button></div>{children}</section></div>; }
